      constructor(scope, id, props) {
         super(scope, id, props);

         new ecsPatterns.ApplicationLoadBalancedFargateServiceStack(this, 'FargateService', {
            cluster: new ecs.Cluster(this, 'MyEcsCluster', {
               vpc: new cdk.Vpc(this, 'MyEcsVpc', {
                  maxAzs: 2,
               }),
            }),
            serviceName: 'MyService',
